ALTER TABLE "assortment"."assortment_rule_revisions" DROP CONSTRAINT "assortment_rule_revisions_selector_ck", ADD CONSTRAINT "assortment_rule_revisions_selector_ck" CHECK ("selector_kind" in ('ALL', 'CATEGORY', 'PRODUCT', 'VARIANT', 'PACKAGE_OPTION') and (("selector_kind" = 'ALL' and "selector_target_owner_module_id" is null and "selector_target_resource_id" is null and "selector_target_resource_type" is null) or ("selector_kind" <> 'ALL' and "selector_target_resource_id" is not null and "selector_target_resource_type" is not null and ("selector_target_owner_module_id" is null or "selector_target_owner_module_id" ~ '^[a-z][a-z0-9]*(?:[.-][a-z0-9]+)*$'))));